import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { SolicitudTipoService } from '../../../controllers/solicitud.tipo.service';

@Component({
  selector: 'app-solicitud-tipo-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './solicitud-tipo-form.html',
  styleUrl: './solicitud-tipo-form.css'
})
export class SolicitudTipoForm implements OnInit {
  public controller = inject(SolicitudTipoService);
  private route = inject(ActivatedRoute);
  public router = inject(Router);
  private fb = inject(FormBuilder);

  public solicitudTipoForm!: FormGroup;
  public isEditMode = false;
  public submitted = false;
  private solicitudTipoId?: number;

  ngOnInit(): void {
    this.initForm();

    this.route.params.subscribe(param => {
      this.solicitudTipoId = param['id'];
      if (this.solicitudTipoId) {
        this.isEditMode = true;
        this.fetchData(this.solicitudTipoId);
      }
    });
  }

  /**
   * Inicializa el formulario con los campos 'nombre' y 'descripcion'
   */
  private initForm(): void {
    this.solicitudTipoForm = this.fb.group({
      nombre: ['', [Validators.required, Validators.minLength(3)]],
      descripcion: ['', [Validators.required, Validators.minLength(5)]]
    });
  }

  private async fetchData(id: number): Promise<void> {
    try {
      const solicitudTipo = await this.controller.find(id);
      this.solicitudTipoForm.patchValue(solicitudTipo!);
    } catch (error) {
      console.error('Error al cargar el tipo de solicitud:', error);
    }
  }

  async onSubmit(): Promise<void> {
    if (this.solicitudTipoForm.invalid) {
      this.solicitudTipoForm.markAllAsTouched();
      return;
    }

    try {
      if (this.isEditMode && this.solicitudTipoId) {
        await this.controller.update(Number(this.solicitudTipoId), this.solicitudTipoForm.value);
        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../../list'], { relativeTo: this.route });
        }, 1500);
      } else {
        const res = await this.controller.new(this.solicitudTipoForm.value);
        if (!res) { return }

        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../list'], { relativeTo: this.route });
        }, 1500);
      }

    } catch (error) {
      console.error('Error al guardar el tipo de solicitud:', error);
    }
  }

  // Getter para acceder fácilmente a los controles del formulario
  get f() {
    return this.solicitudTipoForm.controls;
  }
}