import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { SolicitudGobiernoNivelService } from '../../../controllers/solicitud.gobierno.nivel.service';

@Component({
  selector: 'app-solicitud-gobierno-nivel-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './solicitud-gobierno-nivel-form.html',
  styleUrl: './solicitud-gobierno-nivel-form.css'
})
export class SolicitudGobiernoNivelForm implements OnInit {
  public controller = inject(SolicitudGobiernoNivelService);
  private route = inject(ActivatedRoute);
  public router = inject(Router);
  private fb = inject(FormBuilder);

  public solicitudGobiernoNivelForm!: FormGroup;
  public isEditMode = false;
  public submitted = false;
  private solicitudGobiernoNivelId?: number;

  ngOnInit(): void {
    this.initForm();

    this.route.params.subscribe(param => {
      this.solicitudGobiernoNivelId = param['id'];
      if (this.solicitudGobiernoNivelId) {
        this.isEditMode = true;
        this.fetchData(this.solicitudGobiernoNivelId);
      }
    });
  }

  /**
   * Inicializa el formulario con los campos 'nombre' y 'descripcion'
   */
  private initForm(): void {
    this.solicitudGobiernoNivelForm = this.fb.group({
      nombre: ['', [Validators.required, Validators.minLength(3)]],
      descripcion: ['', [Validators.required, Validators.minLength(5)]]
    });
  }

  private async fetchData(id: number): Promise<void> {
    try {
      const solicitudGobiernoNivel = await this.controller.find(id);
      this.solicitudGobiernoNivelForm.patchValue(solicitudGobiernoNivel!);
    } catch (error) {
      console.error('Error al cargar el orden de gobierno:', error);
    }
  }

  async onSubmit(): Promise<void> {
    if (this.solicitudGobiernoNivelForm.invalid) {
      this.solicitudGobiernoNivelForm.markAllAsTouched();
      return;
    }

    try {
      if (this.isEditMode && this.solicitudGobiernoNivelId) {
        await this.controller.update(Number(this.solicitudGobiernoNivelId), this.solicitudGobiernoNivelForm.value);
        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../../list'], { relativeTo: this.route });
        }, 1500);
      } else {
        const res = await this.controller.new(this.solicitudGobiernoNivelForm.value);
        if (!res) { return }

        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../list'], { relativeTo: this.route });
        }, 1500);
      }

    } catch (error) {
      console.error('Error al guardar el orden de gobierno:', error);
    }
  }

  // Getter para acceder fácilmente a los controles del formulario
  get f() {
    return this.solicitudGobiernoNivelForm.controls;
  }
}