import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { SolicitudTematicaService } from '../../../controllers/solicitud.tematica.service';

@Component({
  selector: 'app-solicitud-tematica-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './solicitud-tematica-form.html',
  styleUrl: './solicitud-tematica-form.css'
})
export class SolicitudTematicaForm implements OnInit {
  public controller = inject(SolicitudTematicaService);
  private route = inject(ActivatedRoute);
  public router = inject(Router);
  private fb = inject(FormBuilder);

  public solicitudTematicaForm!: FormGroup;
  public isEditMode = false;
  public submitted = false;
  private solicitudTematicaId?: number;

  ngOnInit(): void {
    this.initForm();

    this.route.params.subscribe(param => {
      this.solicitudTematicaId = param['id'];
      if (this.solicitudTematicaId) {
        this.isEditMode = true;
        this.fetchData(this.solicitudTematicaId);
      }
    });
  }

  /**
   * Inicializa el formulario con los campos 'nombre', 'codigo' y 'descripcion'
   */
  private initForm(): void {
    this.solicitudTematicaForm = this.fb.group({
      nombre: ['', [Validators.required, Validators.minLength(3)]],
      codigo: [''],
      descripcion: ['', [Validators.required, Validators.minLength(5)]]
    });
  }

  private async fetchData(id: number): Promise<void> {
    try {
      const solicitudTematica = await this.controller.find(id);
      this.solicitudTematicaForm.patchValue(solicitudTematica!);
    } catch (error) {
      console.error('Error al cargar la trámite de solicitud:', error);
    }
  }

  async onSubmit(): Promise<void> {
    if (this.solicitudTematicaForm.invalid) {
      this.solicitudTematicaForm.markAllAsTouched();
      return;
    }

    try {
      if (this.isEditMode && this.solicitudTematicaId) {
        await this.controller.update(Number(this.solicitudTematicaId), this.solicitudTematicaForm.value);
        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../../list'], { relativeTo: this.route });
        }, 1500);
      } else {
        const res = await this.controller.new(this.solicitudTematicaForm.value);
        if (!res) { return }

        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../list'], { relativeTo: this.route });
        }, 1500);
      }

    } catch (error) {
      console.error('Error al guardar la trámite de solicitud:', error);
    }
  }

  // Getter para acceder fácilmente a los controles del formulario
  get f() {
    return this.solicitudTematicaForm.controls;
  }
}