import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { TipoEmpresaService } from '../../../controllers/tipo_empresa.service';

@Component({
  selector: 'app-tipo-empresa-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './tipo-empresa-form.html',
  styleUrl: './tipo-empresa-form.css'
})
export class TipoEmpresaForm implements OnInit {
  public controller = inject(TipoEmpresaService);
  private route = inject(ActivatedRoute);
  public router = inject(Router);
  private fb = inject(FormBuilder);

  public tipoEmpresaForm!: FormGroup;
  public isEditMode = false;
  public submitted = false;
  private tipoEmpresaId?: number;

  ngOnInit(): void {
    this.initForm();

    this.route.params.subscribe(param => {
      this.tipoEmpresaId = param['id'];
      if (this.tipoEmpresaId) {
        this.isEditMode = true;
        this.fetchData(this.tipoEmpresaId);
      }
    });
  }

  /**
   * Inicializa el formulario con los campos 'nombre' y 'descripcion'
   */
  private initForm(): void {
    this.tipoEmpresaForm = this.fb.group({
      nombre: ['', [Validators.required, Validators.minLength(3)]],
      descripcion: ['']
    });
  }

  private async fetchData(id: number): Promise<void> {
    try {
      const tipoEmpresa = await this.controller.find(id);
      this.tipoEmpresaForm.patchValue(tipoEmpresa!);
    } catch (error) {
      console.error('Error al cargar el tipo de empresa:', error);
    }
  }

  async onSubmit(): Promise<void> {
    if (this.tipoEmpresaForm.invalid) {
      this.tipoEmpresaForm.markAllAsTouched();
      return;
    }

    try {
      if (this.isEditMode && this.tipoEmpresaId) {
        await this.controller.update(Number(this.tipoEmpresaId), this.tipoEmpresaForm.value);
        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../../list'], { relativeTo: this.route });
        }, 1500);
      } else {
        const res = await this.controller.new(this.tipoEmpresaForm.value);
        if (!res) { return }

        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../list'], { relativeTo: this.route });
        }, 1500);
      }

    } catch (error) {
      console.error('Error al guardar el tipo de empresa:', error);
    }
  }

  // Getter para acceder fácilmente a los controles del formulario
  get f() {
    return this.tipoEmpresaForm.controls;
  }
}