import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { SectorComercialService } from '../../../controllers/sector.comercial.service';

@Component({
  selector: 'app-sector-comercial-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './sector-comercial-form.html',
  styleUrl: './sector-comercial-form.css'
})
export class SectorComercialForm implements OnInit {
  public controller = inject(SectorComercialService);
  private route = inject(ActivatedRoute);
  public router = inject(Router);
  private fb = inject(FormBuilder);

  public sectorComercialForm!: FormGroup;
  public isEditMode = false;
  public submitted = false;
  private sectorComercialId?: number;

  ngOnInit(): void {
    this.initForm();

    this.route.params.subscribe(param => {
      this.sectorComercialId = param['id'];
      if (this.sectorComercialId) {
        this.isEditMode = true;
        this.fetchData(this.sectorComercialId);
      }
    });
  }

  /**
   * Inicializa el formulario con los campos 'nombre' y 'descripcion'
   */
  private initForm(): void {
    this.sectorComercialForm = this.fb.group({
      nombre: ['', [Validators.required, Validators.minLength(3)]],
      descripcion: ['']
    });
  }

  private async fetchData(id: number): Promise<void> {
    try {
      const sectorComercial = await this.controller.find(id);
      this.sectorComercialForm.patchValue(sectorComercial!);
    } catch (error) {
      console.error('Error al cargar el sector comercial:', error);
    }
  }

  async onSubmit(): Promise<void> {
    if (this.sectorComercialForm.invalid) {
      this.sectorComercialForm.markAllAsTouched();
      return;
    }

    try {
      if (this.isEditMode && this.sectorComercialId) {
        await this.controller.update(Number(this.sectorComercialId), this.sectorComercialForm.value);
        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../../list'], { relativeTo: this.route });
        }, 1500);
      } else {
        const res = await this.controller.new(this.sectorComercialForm.value);
        if (!res) { return }

        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../list'], { relativeTo: this.route });
        }, 1500);
      }

    } catch (error) {
      console.error('Error al guardar el sector comercial:', error);
    }
  }

  // Getter para acceder fácilmente a los controles del formulario
  get f() {
    return this.sectorComercialForm.controls;
  }
}