import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { MunicipioService } from '../../../controllers/municipio.service';

@Component({
  selector: 'app-municipios-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './municipios-form.html',
  styleUrl: './municipios-form.css'
})
export class MunicipiosForm implements OnInit {
  public controller = inject(MunicipioService);
  private route = inject(ActivatedRoute);
  public router = inject(Router);
  private fb = inject(FormBuilder);

  public municipioForm!: FormGroup;
  public isEditMode = false;
  public submitted = false;
  private municipioId?: number;

  ngOnInit(): void {
    this.initForm();

    this.route.params.subscribe(param => {
      this.municipioId = param['id'];
      if (this.municipioId) {
        this.isEditMode = true;
        this.fetchData(this.municipioId);
      }
    });
  }

  /**
   * Inicializa el formulario con el campo 'nombre' y su validación.
   */
  private initForm(): void {
    this.municipioForm = this.fb.group({
      nombre: ['', [Validators.required, Validators.minLength(3)]]
    });
  }

  private async fetchData(id: number): Promise<void> {
    try {
      const municipio = await this.controller.find(id);
      this.municipioForm.patchValue(municipio!);
    } catch (error) {
      console.error('Error al cargar el municipio:', error);
    }
  }

  async onSubmit(): Promise<void> {
    if (this.municipioForm.invalid) {
      this.municipioForm.markAllAsTouched();
      return;
    }

    try {
      if (this.isEditMode && this.municipioId) {
        console.log(this.municipioId)
        await this.controller.update(Number(this.municipioId), this.municipioForm.value);

        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../../list'], { relativeTo: this.route });
        }, 1500);
      } else {
        const res = await this.controller.new(this.municipioForm.value);
        if (!res) { return }

        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../list'], { relativeTo: this.route });
        }, 1500);
      }

    } catch (error) {
      console.error('Error al guardar el municipio:', error);
    }
  }

  // Getter para acceder fácilmente a los controles del formulario
  get f() {
    return this.municipioForm.controls;
  }
}