import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { ActividadEconomicaService } from '../../../controllers/actividad.economica.service';

@Component({
  selector: 'app-actividad-economica-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './actividad-economica-form.html',
  styleUrl: './actividad-economica-form.css'
})
export class ActividadEconomicaForm implements OnInit {
  public controller = inject(ActividadEconomicaService);
  private route = inject(ActivatedRoute);
  public router = inject(Router);
  private fb = inject(FormBuilder);

  public actividadEconomicaForm!: FormGroup;
  public isEditMode = false;
  public submitted = false;
  private actividadEconomicaId?: number;

  ngOnInit(): void {
    this.initForm();

    this.route.params.subscribe(param => {
      this.actividadEconomicaId = param['id'];
      if (this.actividadEconomicaId) {
        this.isEditMode = true;
        this.fetchData(this.actividadEconomicaId);
      }
    });
  }

  /**
   * Inicializa el formulario con todos los campos de actividad económica
   */
  private initForm(): void {
    this.actividadEconomicaForm = this.fb.group({
      codigo: ['', [Validators.required, Validators.minLength(2)]],
      nombre: ['', [Validators.required, Validators.minLength(3)]],
      descripcion: [''],
      sector: [''],
      subsector: [''],
      rama: [''],
      subrama: [''],
      productos: ['']
    });
  }

  private async fetchData(id: number): Promise<void> {
    try {
      const actividadEconomica = await this.controller.find(id);
      this.actividadEconomicaForm.patchValue(actividadEconomica!);
    } catch (error) {
      console.error('Error al cargar la actividad económica:', error);
    }
  }

  async onSubmit(): Promise<void> {
    if (this.actividadEconomicaForm.invalid) {
      this.actividadEconomicaForm.markAllAsTouched();
      return;
    }

    try {
      if (this.isEditMode && this.actividadEconomicaId) {
        await this.controller.update(Number(this.actividadEconomicaId), this.actividadEconomicaForm.value);
        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../../list'], { relativeTo: this.route });
        }, 1500);
      } else {
        const res = await this.controller.new(this.actividadEconomicaForm.value);
        if (!res) { return }

        this.submitted = true;
        setTimeout(() => {
          this.router.navigate(['../list'], { relativeTo: this.route });
        }, 1500);
      }

    } catch (error) {
      console.error('Error al guardar la actividad económica:', error);
    }
  }

  // Getter para acceder fácilmente a los controles del formulario
  get f() {
    return this.actividadEconomicaForm.controls;
  }
}